import test from 'node:test';import assert from 'node:assert/strict';
import {flow} from './opening-flow.mjs';import {ORIGINS} from '../origin-content.js?v=5.6.0';import {legacyFrom,availableOrigins,originLocation,originObjective,inPast,legacyObjects} from '../origins.js?v=5.6.0';import {findPath} from '../navigation.js';import {Battle,encounterEnemies} from '../battle.js?v=5.6.0';import {frontierEnemy} from '../repertoire.js?v=5.6.0';
import {defaultHero} from '../mako.js';
const all={cycle:1,unlocked:[0,1,2,3,4,5,6],records:[]};
function begin(o){const h=flow();h.w.newGame({originId:o.id,legacy:all});h.finish();return h;}
function reachDecision(h,repair=0,battle=false){const w=h.w;h.use(w.objects().find(v=>v.originStep===0));h.use(w.objects().find(v=>v.originStep===1));h.choose(repair);h.use(w.objects().find(v=>v.originTravel));if(battle){h.use(w.objects().find(v=>v.originStep===2&&v.type==='patrol'));assert.ok(w.currentBattle);w.winBattle();h.finish();}else{h.use(w.objects().find(v=>v.originStep===2&&v.type==='puzzle'));h.choose(0);}assert.equal(w.state.chronicle.step,3);}
test('all seven protagonists are selectable before the first playthrough',()=>{assert.equal(availableOrigins(legacyFrom({})).length,7);for(const o of ORIGINS){const h=flow();h.w.newGame({originId:o.id,legacy:legacyFrom({})});assert.equal(h.w.state.party[0],o.hero);}});
test('every protagonist begins with usable combat tools before speaking to the keeper',()=>{for(const o of ORIGINS){const h=begin(o),s=h.w.state,hero=s.heroes[o.hero];assert.deepEqual(hero.loadout,[{core:o.core,support:'focus'}],o.id);assert.equal(hero.mp,hero.maxMp);assert.equal(hero.unlockedSlots,1);assert.ok(hero.learned&128);assert.ok(s.cores.includes(o.core));assert.ok(s.supports.includes('focus'));assert.equal(s.chronicle.step,0);}});
test('keeper preserves levels, mastery, chosen approach and supplies earned by early exploration',()=>{for(const o of ORIGINS){const h=begin(o),w=h.w,s=w.state,hero=s.heroes[o.hero];Object.assign(hero,defaultHero(o.hero,3),{loadout:[{core:o.core,support:'focus'}],ap:{[o.core]:19},battleApproach:'breaker',unlockedSlots:2,hp:113,mp:17});s.gold=34;s.xp=270;s.items.tonic=5;const before=JSON.parse(JSON.stringify(hero));h.use(w.objects().find(v=>v.originStep===0));assert.deepEqual(hero,before,o.id);assert.equal(s.gold,34);assert.equal(s.xp,270);assert.equal(s.items.tonic,5);assert.equal(s.chronicle.step,1);}});
test('worksite exploration and its return route are available without completing origin dialogue',()=>{for(const o of ORIGINS){const h=begin(o),w=h.w;const outward=w.objects().find(v=>v.originTravel===1);assert.ok(outward,o.id);h.use(outward);assert.equal(w.scene.originPart,1);assert.equal(w.state.chronicle.step,0);assert.equal(w.objects().some(v=>v.originStep===2),false,'story threat must remain tied to the repair');const back=w.objects().find(v=>v.originTravel===-1);assert.ok(back,o.id);assert.equal(originObjective(w).object,back);h.use(back);assert.equal(w.scene.originPart,0);assert.equal(w.state.chronicle.step,0);assert.ok(w.objects().some(v=>v.originStep===0));}});
test('Mira origin occupies both actual chapter-five archive wings',()=>{const h=begin(ORIGINS.find(o=>o.hero===5)),w=h.w;for(const [part,source]of[[0,212],[1,213]]){const scene=w.scenes.get(originLocation('mira-archive',part));assert.equal(scene.originSource,source);assert.equal(scene.originIndoor,true);}});
test('all fourteen era maps isolate present events and every visible marker is reachable',()=>{for(const o of ORIGINS){const h=begin(o),w=h.w;assert.deepEqual(w.state.party,[o.hero]);assert.equal(w.state.chronicle.phase,'past');for(const part of[0,1]){const scene=w.scenes.get(originLocation(o.id,part));assert.ok(scene);assert.equal(scene.doors.length,0);for(const obj of scene.objects.filter(v=>v.originId)){const path=findPath(scene,scene.arrive.map(v=>v+.5),obj.xy,1);assert.ok(path.length||Math.hypot(scene.arrive[0]-obj.xy[0],scene.arrive[1]-obj.xy[1])<2,'unreachable '+o.id+' '+obj.label);}}w.loadScene(5);h.finish();assert.equal(w.scene.originId,o.id);assert.ok(originObjective(w).object);}});
test('every origin, repair, encounter approach and civic destiny reaches the present with causal state',()=>{for(const o of ORIGINS)for(const repair of[0,1])for(const fight of[false,true])for(const destiny of[0,1]){const h=begin(o),w=h.w;reachDecision(h,repair,fight);h.use(w.objects().find(v=>v.originStep===3));h.choose(destiny);h.use(w.objects().find(v=>v.originStep===4));h.choose(0);const c=w.state.chronicle;assert.equal(c.phase,'present');assert.equal(c.records.at(-1).effect,o.effects[destiny]);assert.equal(c.records.at(-1).repair,repair);assert.equal(c.records.at(-1).approach,fight?'battle':'diversion');assert.equal(w.state.party[0],o.hero);assert.ok(w.state.recruited.includes(0));assert.equal(w.state.chapter,1);assert.equal(w.state.xp,0);assert.equal(w.state.gold,0);assert.deepEqual(w.state.bosses,[]);assert.equal(w.state.story.parcel,false);assert.equal(w.state.story.firstCore,false);assert.equal(w.scene.key,'home');}});
test('past saves roundtrip at every step and invalid timeline claims are rejected',()=>{for(const o of ORIGINS){const h=begin(o),w=h.w;const replay=()=>{const save=w.save(),before=JSON.parse(save);w.restore(save);assert.equal(w.state.chronicle.step,before.chronicle.step);assert.equal(w.state.party[0],o.hero);};replay();h.use(w.objects().find(v=>v.originStep===0));replay();h.use(w.objects().find(v=>v.originStep===1));h.choose();replay();h.use(w.objects().find(v=>v.originTravel));replay();h.use(w.objects().find(v=>v.originStep===2&&v.type==='patrol'));const active=w.currentBattle.object;const state=w.save();w.restore(state);assert.ok(w.objects().some(v=>v.originId===active.originId&&v.bit===active.bit));const bad=JSON.parse(state);bad.chronicle.originId='missing';assert.throws(()=>w.restore(bad),/Invalid origin/);}});
test('inherited services exist in actual present regions, pay once, and earlier decisions survive another origin',()=>{const h=begin(ORIGINS[0]),w=h.w;reachDecision(h);h.use(w.objects().find(v=>v.originStep===3));h.choose(0);h.use(w.objects().find(v=>v.originStep===4));h.choose();let found;for(const s of w.data.scenes.filter(s=>!s.originId&&s.chapter===1)){w.state.scene=s.location;found=legacyObjects(w)[0];if(found)break;}assert.ok(found,'present inheritance missing');h.use(found);h.choose();assert.equal(w.state.items.tonic,2);h.use(found);h.choose();assert.equal(w.state.items.tonic,2);const old=w.state.chronicle.records[0];const legacy=legacyFrom(w.state);legacy.unlocked.push(2);w.newGame({originId:ORIGINS[2].id,legacy});h.finish();assert.deepEqual(w.state.chronicle.records[0],old);assert.ok(Object.values(w.state.flags).every(v=>v===0));assert.equal(inPast(w),true);});
test('each origin encounter is winnable by its actual solo hero without unrecruited skills',()=>{for(const o of ORIGINS){const h=begin(o),w=h.w;h.use(w.objects().find(v=>v.originStep===0));h.use(w.objects().find(v=>v.originStep===1));h.choose();h.use(w.objects().find(v=>v.originTravel));const obj=w.objects().find(v=>v.type==='patrol'),enemy=frontierEnemy(encounterEnemies(1,false,1)[0],obj.originSpecies);enemy.hp=enemy.maxHp=Math.round(enemy.maxHp*obj.originScale);enemy.power=Math.round(enemy.power*.7);enemy.x=1;enemy.y=0;const hero=w.activeHeroes[0];hero.x=0;hero.y=0;const battle=new Battle({heroes:[hero],enemies:[enemy],chapter:1});for(let i=0;i<3000&&!battle.ended;i++){battle.advance(.1);for(const ready of battle.ready)battle.command(ready.id,'attack',battle.livingEnemies[0]?.id);}assert.equal(battle.ended,'win',o.id);}});

test('timeline eras and discovered boss patterns follow the chosen history without carrying owned equipment',()=>{const h=flow(),w=h.w;w.state.complete=true;w.state.bossGear={version:1,patterns:['guardian-1'],owned:['guardian-1'],claims:['main:1']};const legacy=legacyFrom(w.state);w.newGame({originId:ORIGINS[2].id,legacy});h.finish();assert.equal(w.state.timeline.era,'origin');assert.deepEqual(w.state.bossGear.patterns,['guardian-1']);assert.deepEqual(w.state.bossGear.owned,[]);reachDecision(h);h.use(w.objects().find(v=>v.originStep===3));h.choose();h.use(w.objects().find(v=>v.originStep===4));h.choose();assert.equal(w.state.timeline.era,'present');assert.deepEqual(w.state.bossGear.patterns,['guardian-1']);assert.deepEqual(w.state.bossGear.owned,[]);assert.deepEqual(w.state.bossGear.claims,[]);});
